{
  "claims": [
    {
      "claim_id": "F1",
      "en": "A balance service summary returns a dictionary with account, available_minor, and currency.",
      "pt_br": "Um serviço de balanceamento retorna um dicionário com conta, disponível_minor e moeda."
    },
    {
      "claim_id": "F2",
      "en": "The BalanceAdapter constructor has a default timeout of 2.0 seconds.",
      "pt_br": "O construtor BalanceAdapter tem um tempo de espera padrão de 2.0 segundos."
    },
    {
      "claim_id": "F3",
      "en": "The BalanceAdapter.read method raises a BalanceUnavailable exception if the gateway is unavailable.",
      "pt_br": "O método read do BalanceAdapter lança uma exceção BalanceUnavailable se o gateway estiver indisponível."
    },
    {
      "claim_id": "F4",
      "en": "The BalanceAdapter.read method calls the balance_from_payload function with the account_id and payload as arguments.",
      "pt_br": "O método read do BalanceAdapter chama a função balance_from_payload com o account_id e o payload como argumentos."
    },
    {
      "claim_id": "F5",
      "en": "The JsonClient.get method is a declared protocol only method.",
      "pt_br": "O método get do JsonClient é um método protocolo apenas declarado."
    },
    {
      "claim_id": "F6",
      "en": "The BalanceAdapter.read method does not have a written exception handler in its selected body.",
      "pt_br": "O método read do BalanceAdapter não tem um manipulador de exceção escrito em seu corpo selecionado."
    }
  ]
}
